package com.ivy.data.backup.local

import androidx.hilt.work.WorkerAssistedFactory
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Guards the wiring that makes the SCHEDULED backup actually run.
 *
 * `@HiltWorker` on [LocalBackupWorker] is only an annotation: the code that lets
 * `HiltWorkerFactory` build the worker (the `<Worker>_AssistedFactory` interface plus the
 * `@IntoMap @StringKey(...)` binding of it in `SingletonComponent`) is generated by
 * `androidx.hilt:hilt-compiler`. When that processor is not on the module's KSP processor path
 * everything still compiles and the manual "Back up now" still works, because that path calls the
 * repository directly - but `HiltWorkerFactory` has no entry for the worker, so
 * `WorkerFactory.createWorker()` returns null and WorkManager falls back to reflectively calling
 * `Worker.<init>(Context, WorkerParameters)`, which an `@AssistedInject` worker does not have:
 *
 * ```
 * WM-WorkerFactory: Could not instantiate com.ivy.data.backup.local.LocalBackupWorker
 * java.lang.NoSuchMethodException: ...LocalBackupWorker.<init>[Context, WorkerParameters]
 * ```
 *
 * That was the Phase 5 defect: the periodic backup silently never ran.
 *
 * Asserting the generated types exist is the cheapest way to pin the processor wiring - they are
 * produced if and only if `androidx.hilt:hilt-compiler` ran over this module.
 */
class LocalBackupWorkerWiringTest {

    @Test
    fun `the hilt worker compiler generated the assisted factory HiltWorkerFactory needs`() {
        val assistedFactory = Class.forName(ASSISTED_FACTORY)

        assertTrue(
            "$ASSISTED_FACTORY must implement androidx.hilt.work.WorkerAssistedFactory, otherwise " +
                "HiltWorkerFactory cannot build LocalBackupWorker and WorkManager falls back to " +
                "the (Context, WorkerParameters) constructor that it does not have",
            WorkerAssistedFactory::class.java.isAssignableFrom(assistedFactory),
        )
    }

    @Test
    fun `the generated hilt module contributes the worker to the WorkManager factory map`() {
        // Holds @IntoMap @StringKey("com.ivy.data.backup.local.LocalBackupWorker"), i.e. the entry
        // HiltWorkerFactory looks the worker up by. Class.forName throws when it is missing.
        Class.forName(HILT_MODULE)
    }

    private companion object {
        const val ASSISTED_FACTORY = "com.ivy.data.backup.local.LocalBackupWorker_AssistedFactory"
        const val HILT_MODULE = "com.ivy.data.backup.local.LocalBackupWorker_HiltModule"
    }
}
